def PANO(t):
    import ctypes
    u=ctypes.windll.user32; kk=ctypes.windll.kernel32
    kk.GlobalAlloc.restype=ctypes.c_void_p; kk.GlobalLock.restype=ctypes.c_void_p
    kk.GlobalLock.argtypes=[ctypes.c_void_p]; kk.GlobalUnlock.argtypes=[ctypes.c_void_p]
    u.SetClipboardData.argtypes=[ctypes.c_uint,ctypes.c_void_p]
    d=(t+"\0").encode("utf-16le")
    h=kk.GlobalAlloc(0x42,len(d)); p=kk.GlobalLock(h); ctypes.memmove(p,d,len(d)); kk.GlobalUnlock(h)
    u.OpenClipboard(None); u.EmptyClipboard(); u.SetClipboardData(13,h); u.CloseClipboard()

import http.server,socketserver,urllib.parse,mimetypes,uuid,hashlib,zlib
IZIN=os.path.join(base,"izinli.json")
SERV={}; GIZ=[""]
def _izinYukle():
    try:
        with open(IZIN,encoding="utf-8") as f: d=json.load(f)
        GIZ[0]=str(d.get("s") or "")
        for k,v in (d.get("y") or {}).items():
            if isinstance(v,str): SERV[k]=v
    except Exception: pass
    if not GIZ[0]: GIZ[0]=uuid.uuid4().hex
def _izinYaz():
    try:
        y=dict(list(SERV.items())[-3000:])
        with open(IZIN,"w",encoding="utf-8") as f: json.dump({"s":GIZ[0],"y":y},f)
    except Exception: LOG("izinli.json yazılamadı: "+traceback.format_exc()[-300:])
_izinYukle()
class _H(http.server.BaseHTTPRequestHandler):
    def log_message(s,*a): pass
    def do_HEAD(s): s._ver(False)
    def do_GET(s): s._ver(True)
    def _ver(s,govde):
        try:
            t=urllib.parse.urlparse(s.path).path.strip("/").split("/")[0]
            p=SERV.get(t)
            if not p or not os.path.isfile(p):
                s.send_response(404); s.end_headers(); return
            n=os.path.getsize(p); a=0; b=n-1; kod=200
            r=s.headers.get("Range")
            if r and r.startswith("bytes=") and n>0:
                try:
                    x,_,y=r[6:].partition("-")
                    if x=="": a=max(0,n-int(y))
                    else:
                        a=int(x)
                        if y: b=min(int(y),n-1)
                    kod=206
                except Exception:
                    a=0; b=n-1; kod=200
                if a>b or a>=n:
                    s.send_response(416); s.send_header("Content-Range","bytes */%d"%n); s.end_headers(); return
            tur=mimetypes.guess_type(p)[0] or "application/octet-stream"
            s.send_response(kod)
            s.send_header("Content-Type",tur); s.send_header("Accept-Ranges","bytes")
            s.send_header("Content-Length",str(max(0,b-a+1)))
            if kod==206: s.send_header("Content-Range","bytes %d-%d/%d"%(a,b,n))
            s.end_headers()
            if not govde or n==0: return
            with open(p,"rb") as f:
                f.seek(a); k=b-a+1
                while k>0:
                    d=f.read(min(65536,k))
                    if not d: break
                    s.wfile.write(d); k-=len(d)
        except Exception:
            pass
class _S(socketserver.ThreadingMixIn,http.server.HTTPServer):
    daemon_threads=True
    allow_reuse_address=(os.name!="nt")
SRV=[None]
def yayinBaslat():
    if SRV[0] is not None: return
    p0=47000+zlib.crc32(NAME.encode("utf-8"))%2000
    sv=None
    for pt in list(range(p0,p0+25))+[0]:
        try:
            sv=_S(("127.0.0.1",pt),_H); break
        except OSError: sv=None
    if sv is None: raise OSError("yerel sunucu açılamadı")
    SRV[0]=sv
    threading.Thread(target=sv.serve_forever,daemon=True).start()
def yayin(p):
    try:
        yayinBaslat()
        pm=os.path.abspath(p)
        t=hashlib.sha1((GIZ[0]+os.path.normcase(pm)).encode("utf-8")).hexdigest()[:24]
        if SERV.get(t)!=pm:
            SERV[t]=pm; _izinYaz()
        return "http://127.0.0.1:%d/%s/%s"%(SRV[0].server_address[1],t,urllib.parse.quote(os.path.basename(pm)))
    except Exception:
        LOG("yayin hatası: "+traceback.format_exc()[-300:])
        return pathlib.Path(p).as_uri()
def DOSYA(a):
    tur,_,co=a.partition("|")
    F={"resim":"Resimler (*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp)","ses":"Ses (*.mp3;*.wav;*.ogg;*.m4a;*.flac)","video":"Video (*.mp4;*.webm;*.mkv;*.avi;*.mov)"}
    ft=(F.get(tur,"Medya (*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp;*.mp3;*.wav;*.ogg;*.m4a;*.flac;*.mp4;*.webm;*.mkv;*.avi;*.mov)"),"Tüm dosyalar (*.*)")
    try: l=dlg("open",directory=os.path.expanduser("~"),allow_multiple=(co=="1"),file_types=ft)
    except Exception:
        LOG("DOSYA filtre hatası: "+traceback.format_exc()[-300:])
        l=dlg("open",allow_multiple=(co=="1"))
    LOG("DOSYA seçildi: "+json.dumps(l))
