WEBS={}; FR={}; RZ=[False]
GIZLI=set(); POP=[0]
def gorun(i): WEBS[i].Visible=(i not in GIZLI and not POP[0])
def adres(u):
    u=u.strip()
    return u if "://" in u else "https://"+u
HOLES={}
def maske_i(i):
    from System.Drawing import Rectangle,Region
    o=WEBS[i]; b=o.Bounds; h=HOLES.get(i) or []
    if not h:
        o.Region=None; return
    cs=win.native.ClientSize; reg=Region(Rectangle(0,0,b.Width,b.Height))
    for x,y,w_,h_ in h: reg.Exclude(Rectangle(int(x*cs.Width)-b.X,int(y*cs.Height)-b.Y,int(w_*cs.Width)+1,int(h_*cs.Height)+1))
    o.Region=reg
def yerlestir(i):
    from System.Drawing import Rectangle
    cs=win.native.ClientSize; l,t,w_,h_=FR[i]
    WEBS[i].Bounds=Rectangle(int(l*cs.Width),int(t*cs.Height),int(w_*cs.Width),int(h_*cs.Height))
    maske_i(i)
def web_isle(k,a):
    d=json.loads(a)
    def run():
        from System import Uri,EventHandler
        from Microsoft.Web.WebView2.WinForms import WebView2,CoreWebView2CreationProperties
        form=win.native
        if not RZ[0]:
            RZ[0]=True
            form.Resize+=EventHandler(lambda s,e:[yerlestir(i) for i in list(WEBS)])
        if k=="WEBTUM":
            POP[0]=0 if d else 1
            for i in list(WEBS): gorun(i)
        elif k=="WEBMASKE":
            HOLES[d[0]]=d[1]
            if d[0] in WEBS: maske_i(d[0])
        elif k=="WEBEKLE":
            o=WEBS.get(d[0])
            if o is None:
                o=WebView2(); cp=CoreWebView2CreationProperties(); cp.UserDataFolder=os.path.join(base,"web"); o.CreationProperties=cp
                o.Source=Uri(adres(d[1])); WEBS[d[0]]=o; form.Controls.Add(o)
            FR[d[0]]=(d[2],d[3],d[4],d[5]); yerlestir(d[0]); GIZLI.discard(d[0]); gorun(d[0]); o.BringToFront()
        elif k=="WEBGIT" and d[0] in WEBS: WEBS[d[0]].Source=Uri(adres(d[1]))
        elif k=="WEBGOR" and d[0] in WEBS:
            GIZLI.discard(d[0]) if d[1] else GIZLI.add(d[0])
            gorun(d[0])
    try:
        from System import Action
        win.native.Invoke(Action(run))
    except Exception:
        LOG(traceback.format_exc())
        if k=="WEBEKLE": ej("UGCO.webYedek(%s,%s)"%(json.dumps(d[0]),json.dumps(adres(d[1]))))
def _SYS32(ad):
    return os.path.join(os.environ.get("SystemRoot","C:\\Windows"),"System32",ad)
def _CALIS(cmd,shell=False):
    import subprocess
    r=subprocess.run(cmd,shell=shell,creationflags=0x08000000,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=60)
    if r.returncode!=0:
        LOG("komut hata %s: %s %s"%(r.returncode,r.stdout[-200:],r.stderr[-200:]))
    return r.returncode
def UYGAC(yol):
    yol=str(yol).strip().strip('"')
    try:
        if os.path.exists(yol): os.startfile(yol); return
    except Exception: LOG(traceback.format_exc())
    import subprocess
    subprocess.Popen(yol,shell=True,creationflags=0x08000000,stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
def BATCHAL(cmd):
    import subprocess
    subprocess.Popen(cmd,shell=True,creationflags=0x08000000,stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
def PCEYLEM(a):
    d=json.loads(a); e=d.get("eylem","shutdown")
    try: s=max(0,int(float(d.get("sure",3))))
    except Exception: s=3
    if e=="shutdown": c=[_SYS32("shutdown.exe"),"/s","/t",str(s)]
    elif e=="restart": c=[_SYS32("shutdown.exe"),"/r","/t",str(s)]
    elif e=="logoff": c=[_SYS32("shutdown.exe"),"/l"]
    else: return
    threading.Thread(target=lambda:_CALIS(c),daemon=True).start()
def _SESCOM(islem,deger=0):
    import ctypes
    from ctypes import POINTER,byref,c_void_p,c_float,c_int,c_uint32,c_ushort,c_ubyte,c_long,WINFUNCTYPE
    class G(ctypes.Structure):
        _fields_=[("a",c_uint32),("b",c_ushort),("c",c_ushort),("d",c_ubyte*8)]
    def gid(t):
        g=G(); ctypes.oledll.ole32.CLSIDFromString(ctypes.c_wchar_p(t),byref(g)); return g
    def vc(p,i,*sig):
        tb=ctypes.cast(ctypes.cast(p,POINTER(c_void_p))[0],POINTER(c_void_p))
        return WINFUNCTYPE(c_long,c_void_p,*sig)(tb[i])
    ole=ctypes.windll.ole32
    ole.CoInitialize(None)
    en=c_void_p(); dev=c_void_p(); ev=c_void_p()
    try:
        r=ole.CoCreateInstance(byref(gid("{BCDE0395-E52F-467C-8E3D-C4579291692E}")),None,23,byref(gid("{A95664D2-9614-4F35-A746-DE8DB63617E6}")),byref(en))
        if r!=0: raise OSError("CoCreateInstance "+str(r))
        r=vc(en.value,4,c_int,c_int,POINTER(c_void_p))(en.value,0,1,byref(dev))
        if r!=0: raise OSError("GetDefaultAudioEndpoint "+str(r))
        r=vc(dev.value,3,POINTER(G),c_uint32,c_void_p,POINTER(c_void_p))(dev.value,byref(gid("{5CDF2C82-841E-4546-9722-0CF74078229A}")),23,None,byref(ev))
        if r!=0: raise OSError("Activate "+str(r))
        f=c_float(); m=c_int()
        vc(ev.value,9,POINTER(c_float))(ev.value,byref(f))
        if islem=="degis":
            yeni=max(0.0,min(1.0,f.value+deger))
            vc(ev.value,7,c_float,c_void_p)(ev.value,yeni,None); f.value=yeni
        elif islem=="ayar":
            yeni=max(0.0,min(1.0,float(deger)/100.0))
            vc(ev.value,7,c_float,c_void_p)(ev.value,yeni,None); f.value=yeni
        elif islem=="sessiz":
            vc(ev.value,14,c_int,c_void_p)(ev.value,1 if deger else 0,None)
        vc(ev.value,15,POINTER(c_int))(ev.value,byref(m))
        return 0 if m.value else int(round(f.value*100))
    finally:
        for o in (ev,dev,en):
            if o.value:
                try: vc(o.value,2)(o.value)
                except Exception: pass
        try: ole.CoUninitialize()
        except Exception: pass
def SESSIS(eylem):
    def run():
        try:
            if eylem=="kis": _SESCOM("degis",-0.10)
            elif eylem=="yukselt": _SESCOM("degis",0.10)
            elif eylem=="ac": _SESCOM("sessiz",0)
            elif eylem=="kapat": _SESCOM("sessiz",1)
        except Exception:
            LOG("SESSIS: "+traceback.format_exc()[-400:])
    threading.Thread(target=run,daemon=True).start()
SESBEK=[None]; SESKIL=threading.Lock()
def SESAYAR(a):
    try: SESBEK[0]=max(0.0,min(100.0,float(a)))
    except Exception: return
    def run():
        while True:
            if not SESKIL.acquire(False): return
            try:
                x=SESBEK[0]; SESBEK[0]=None
                if x is not None: _SESCOM("ayar",x)
            except Exception:
                LOG("SESAYAR: "+traceback.format_exc()[-400:])
            finally:
                SESKIL.release()
            if SESBEK[0] is None: return
    threading.Thread(target=run,daemon=True).start()
SESD=[False]
def SESOKU(a=""):
    if SESD[0]: return
    SESD[0]=True
    def dongu():
        son=None; n=0
        while True:
            try:
                d=_SESCOM("oku")
                if d!=son or n%4==0:
                    if win is not None: ej("window.ugcoSesDuzey(%d)"%d)
                    son=d
            except Exception:
                if n==0: LOG("SESOKU: "+traceback.format_exc()[-400:])
            n+=1; time.sleep(0.6)
    threading.Thread(target=dongu,daemon=True).start()
def isle(k,a):
    if k=="KAPAT": win.destroy()
    elif k.startswith("WEB"): web_isle(k,a)
    elif k=="LINK": webbrowser.open(a)
    elif k=="PANO": PANO(a)
    elif k=="DOSYA": DOSYA(a)
    elif k=="METINOKU": METINOKU()
    elif k=="METINYAZ": METINYAZ(a)
    elif k=="RESIMKAYDET": RESIMKAYDET(a)
    elif k=="UYGAC": UYGAC(a)
    elif k=="BATCHAL": BATCHAL(a)
    elif k=="PCEYLEM": PCEYLEM(a)
    elif k=="SESSIS": SESSIS(a)
    elif k=="SESOKU": SESOKU(a)
    elif k=="SESAYAR": SESAYAR(a)
    pass
